mapper.select:
SELECT, status
FROM document
WHERE id = #{id}

SELECT, status
FROM document
WHERE status != 'deleted'

    AND id = #{id}


    AND doc_id = #{docId}


    AND data_source_id = #{dataSourceId}


    AND channel = #{channel}


    AND name LIKE CONCAT('%', #{name}, '%')


    AND (
    
        
            file_type IN ('xlsx', 'xls')
        
        
            file_type IN ('doc', 'docx')
        
        
            file_type IN ('ppt', 'pptx')
        
        
            file_type IN ('markdown', 'md')
        
        
            file_type NOT IN ('ppt', 'pptx','doc', 'docx','xlsx', 'xls','pdf','md','markdown')
        
        
            file_type = #{fileType}
        
    
    )


    AND doc_type = #{docType}


    AND source_name = #{sourceName}


    AND source_status = #{sourceStatus}


    AND switch_status = #{switchStatus}


    AND task_status = #{taskStatus}


    AND (name LIKE CONCAT('%', #{keyword}, '%') OR doc_id LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY update_time DESC

SELECT d.id, d.doc_id as docId, d.data_source_id as dataSourceId, d.channel, d.name, d.file_type as fileType, d.doc_type as docType, d.doc_type_name as docTypeName, d.source_name as sourceName, d.source_status as sourceStatus, d.switch_status as switchStatus, d.task_status as taskStatus, d.last_process_time as lastProcessTime, d.md5, d.file_size as fileSize, d.creator, d.create_time as createTime, d.modifier, d.update_time as updateTime, d.visibility, d.xsky_path as xskyPath, d.bucket_name as bucketName, d.bucket_path as bucketPath, d.vector_enabled as vectorEnabled, d.vector_id as vectorId, d.metadata, d.parent_doc_name as parentDocName, d.is_attachment as isAttachment, d.own_dataset_id as ownDatasetId, d.status as status FROM document d WHERE d.status != 'deleted'
AND d.doc_type = #{docType}
AND d.creator = #{creator}
AND d.channel = #{channel}
AND (d.name LIKE CONCAT('%', #{keyword}, '%') OR d.doc_id LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.update_time DESC

